KG42.register("rules-4315138f0c661516dc4e4f3c",{"id":"10-hierarchical_coordination::v141-c-R013","paper":"10-hierarchical_coordination","record":{"rule_id":"v141-c-R013","mechanism_id":"v141-a-M02","name":"Local clearing price","process_stage":"pricing","market_meaning":"Matching the prosumer counterparties precedes calculation of their pair-specific P2P trading price. Scope: First-stage local P2P market under coordinating strategy one; pricing for a matched prosumer pair. Each P2P transaction has its own matching price, which does not depend on the other P2P transactions in the local market. Scope: Local P2P transactions under LMO coordinating strategy one. The P2P trading price equals the arithmetic mean of the corresponding offering and bidding prices. Scope: Pair-specific local P2P pricing under coordinating strategy one, for distinct prosumers j and i at time t. Condition: For the pair matched by the LMO.","independence_rationale":"Relations governed by the approved function pricing.local under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["matching.counterparties","pricing.local"],"E":[{"edge_id":"v141-c-R013-E001","source":"matching.counterparties","target":"pricing.local","type":"precedes","constraint_ids":["v141-c-R013-C001"],"evidence_ids":["v141-b-g02-e24"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"First-stage local P2P market under coordinating strategy one; pricing for a matched prosumer pair. | Local P2P transactions under LMO coordinating strategy one. | Pair-specific local P2P pricing under coordinating strategy one, for distinct prosumers j and i at time t.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e02","v141-b-g02-e20","v141-b-g02-e24"]},"x":[{"variable_id":"x_lambda_p2p_jit","symbol":"\\lambda^{p2p}_{jit}","meaning":"Price of P2P energy trading between prosumers j and i at time slot t, determined after matching according to Eq. (26).","kind":"operational","domain":"real-valued price (no explicit numeric bounds are provided in the quoted evidence)","unit":null,"indices":["j","i","t"],"evidence_ids":["v141-b-g02-e24"]}],"theta":[{"parameter_id":"theta_lambda_o_jt","symbol":"\\lambda^{o}_{jt}","meaning":"Offering price of prosumer j at time t, used as an input to the local P2P pricing rule. The quoted Eq. (26) uses no block index, while Eq. (24) and the nomenclature define \\lambda^{o}_{jtm} with block index m; this discrepancy is left unresolved.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["j","t"],"evidence_ids":["v141-b-g02-e20","v141-b-g02-e24"]},{"parameter_id":"theta_lambda_b_it","symbol":"\\lambda^{b}_{it}","meaning":"Bidding price of prosumer i at time t, used as an input to the local P2P pricing rule. The quoted Eq. (26) uses no block index, while Eq. (24) and the nomenclature define \\lambda^{b}_{itm} with block index m; this discrepancy is left unresolved.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g02-e20","v141-b-g02-e24"]}],"phi":[{"constraint_id":"v141-c-R013-C001","kind":"procedural","role":"core","statement":"Matching the prosumer counterparties precedes calculation of their pair-specific P2P trading price. Scope: First-stage local P2P market under coordinating strategy one; pricing for a matched prosumer pair.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["matching.counterparties","pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e24"]},{"constraint_id":"v141-c-R013-C002","kind":"procedural","role":"core","statement":"Each P2P transaction has its own matching price, which does not depend on the other P2P transactions in the local market. Scope: Local P2P transactions under LMO coordinating strategy one.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e02"]},{"constraint_id":"v141-c-R013-C003","kind":"mathematical","role":"core","statement":"The P2P trading price equals the arithmetic mean of the corresponding offering and bidding prices. Scope: Pair-specific local P2P pricing under coordinating strategy one, for distinct prosumers j and i at time t. Condition: For the pair matched by the LMO.","expression":"\\lambda^{p2p}_{jit} = (\\lambda^{o}_{jt} + \\lambda^{b}_{it}) / 2, \\forall j, j \\neq i, \\forall t","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["x_lambda_p2p_jit"],"parameter_refs":["theta_lambda_o_jt","theta_lambda_b_it"],"evidence_ids":["v141-b-g02-e20","v141-b-g02-e24"]}],"pi":[{"evidence_id":"v141-b-g02-e02","location":{"location_id":"src-87ebdce2a6-p04-c1r2__v141-a-M02-pricing","page":4,"printed_page":null,"section":"2.1. First stage: P2P energy market","anchor_text":"Fig. 1. Players and our proposed framework for e 2.1. First stage: P2P energy market LE 𝜆−𝑡 In the f","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Although the LMO is in charge of coordinating P2P matches in the local market, each P2P energy trading has its corresponding matching price which does not depend on the rest of P2P transactions in the LEM."},{"evidence_id":"v141-b-g02-e20","location":{"location_id":"src-87ebdce2a6-p05-c2r1__v141-a-M02-clearing","page":5,"printed_page":null,"section":"2.1.2. P2P coordinating problem","anchor_text":"Applied Energy 302 (2021) 117575 to where 𝑃𝑝2𝑝,+,𝑏𝑙𝑗𝑖𝑡𝑚 and 𝑃𝑝2𝑝,−,𝑏𝑙𝑗𝑖𝑡, express the quantity of of","equation_id":"(24)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"In this paper, we propose two coordinating strategies for P2P energy trading in the LEM. In strategy one, \\Upsilon^{1}, the LMO coordinates the P2P energy transactions locally to maximize matching the offering and bidding blocks submitted by prosumers as presented in (24): OF^{1} = \\sum_{jtm} \\sum_{i(i \\neq j)} (\\lambda^{o}_{jtm} P^{p2p,+,bl}_{jitm} - \\lambda^{b}_{itm} P^{p2p,-,bl}_{jitm}),   (24) where \\lambda^{o}_{jtm} and \\lambda^{b}_{itm} present offering and bidding prices for P2P trading between prosumers j and i at time t and block m which are outputs of bidding strategy problem for prosumer j. Moreover, it is noted that \\lambda^{o}_{jtm} (\\lambda^{b}_{jtm}) are different with \\lambda^{lm}_{jt\\omega} which is an input of bidding strategy problem for prosumer j."},{"evidence_id":"v141-b-g02-e24","location":{"location_id":"src-87ebdce2a6-p05-c2r3__v141-a-M02-pricing","page":5,"printed_page":null,"section":"2.1.2. P2P coordinating problem","anchor_text":"of ∑ ∑ 𝑂𝐹2 = 𝑃𝑝2𝑝,+𝑗𝑖𝑡 , (25)ng 𝑗 𝑖(𝑖≠𝑗)𝑡 it ne here, the P2P coordinating problem for strategy two ","equation_id":"(26)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"In this way, after the LMO matches P2P energy trading between prosumers i and j, their P2P trading price is obtained in Eq. (26): \\lambda^{p2p}_{jit} = (\\lambda^{o}_{jt} + \\lambda^{b}_{it}) / 2, \\forall j, j \\neq i, \\forall t   (26) where \\lambda^{p2p}_{jit} represents the price of P2P energy trading between prosumers j and i."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M02-clearing","v141-a-M02-matching","v141-a-M02-pricing","v141-a-M03-pricing"],"extras":{"decision_anchor":"pricing.local","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e24","quote":"In this way, after the LMO matches P2P energy trading between prosumers i and j, their P2P trading price is obtained in Eq. (26):"}],[{"evidence_id":"v141-b-g02-e02","quote":"each P2P energy trading has its corresponding matching price which does not depend on the rest of P2P transactions in the LEM."}],[{"evidence_id":"v141-b-g02-e24","quote":"\\lambda^{p2p}_{jit} = (\\lambda^{o}_{jt} + \\lambda^{b}_{it}) / 2, \\forall j, j \\neq i, \\forall t   (26) where \\lambda^{p2p}_{jit} represents the price of P2P energy trading between prosumers j and i."},{"evidence_id":"v141-b-g02-e20","quote":"where \\lambda^{o}_{jtm} and \\lambda^{b}_{itm} present offering and bidding prices for P2P trading between prosumers j and i at time t and block m"}]],"C2_formalization":{"graph_sha256":"cc33415d836f6ff41b45a437324fd053b0d5aef8ee9b14995400c6e021a2d412","applicability":"formalized","reason":"Eq. (26) from the quoted evidence defines the pair-specific local P2P trading price as the arithmetic mean of the offering price of prosumer j and the bidding price of prosumer i. The frozen graph's pricing.local node and matching.counterparties -> pricing.local precedence edge are sufficient to scope the formula. The offering and bidding prices are treated as symbolic inputs to this pricing rule, consistent with the source statement that they are outputs of the prosumer bidding-strategy problem. B evidence remains unreviewed, so the transcription is provisional.","bindings":[{"object_id":"x_lambda_p2p_jit","node_ids":["pricing.local"],"edge_ids":["v141-c-R013-E001"],"rationale":"The pair-specific P2P trading price is the output object of the local pricing rule. It belongs to pricing.local, and E001 records that this pricing computation follows matching.counterparties, as required by the source phrase 'after the LMO matches P2P energy trading between prosumers i and j'."},{"object_id":"theta_lambda_o_jt","node_ids":["pricing.local"],"edge_ids":[],"rationale":"The offering price of prosumer j is an input to the pricing.local formula in Eq. (26). The frozen graph for this rule contains no separate bidding-price node, so the input is scoped to pricing.local and declared as a symbolic parameter rather than a design or operational decision made inside this pricing rule."},{"object_id":"theta_lambda_b_it","node_ids":["pricing.local"],"edge_ids":[],"rationale":"The bidding price of prosumer i is an input to the pricing.local formula in Eq. (26). The frozen graph for this rule contains no separate bidding-price node, so the input is scoped to pricing.local and declared as a symbolic parameter rather than a design or operational decision made inside this pricing rule."},{"object_id":"v141-c-R013-C003","node_ids":["pricing.local"],"edge_ids":["v141-c-R013-E001"],"rationale":"Eq. (26) is the pricing.local rule for the matched pair. E001 records the matching.counterparties -> pricing.local precedence, which is the only frozen edge directly relevant to the formula's 'after the LMO matches' condition."}],"revision_requests":["B evidence is unreviewed. Independent source audit is required to confirm the exact transcription of Eq. (26), including the absence of the block index m in \\lambda^{o}_{jt} and \\lambda^{b}_{it} despite the m-indexed definitions in Eq. (24) and the nomenclature.","Eq. (26) is stated in the source text as applying after matching and is introduced in a passage saying 'in both strategies'; the frozen rule is scoped to strategy one. Confirm whether this pricing rule should be represented as shared by strategy two or duplicated with strategy-specific scope.","The frozen graph for this rule contains only matching.counterparties and pricing.local. The offering and bidding prices are source-identified as outputs of the prosumer bidding strategy but have no dedicated node here. C.1 should confirm whether they should remain symbolic inputs to pricing.local or whether bidding.supply/bidding.demand nodes should be added to this rule's graph for a fuller formalization.","No unit is explicitly attached to \\lambda^{p2p}_{jit}, \\lambda^{o}_{jt}, or \\lambda^{b}_{it} in the quoted evidence. The unit fields are left null rather than inferred."]},"C2_delivery":{"raw_sha256":"ec1c507dc3cd61045e6fd1e533a7c04a8d85f6e17fda782d2036d3b3623b693e","delivery_payload_sha256":"c12c8f6749b41a7a1d3ffb1d781fb9a33e910ee7d8e391ebf255d32d98db4700","changes":[{"path":"theta.0.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.1.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"cc33415d836f6ff41b45a437324fd053b0d5aef8ee9b14995400c6e021a2d412","scientific_correctness_verified":false}},"quarantined_references":[]}});
